def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = beads[i]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = max(dp[i][k] + dp[k + 1][j] * beads[k] for k in range(i, j))

    return dp[0][n - 1]
