def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not coeffs or n < 0:
        return "Invalid input"

    result = []
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        if i == n:
            term = f"{abs(coeff)}x^{n}"
        elif i == 0:
            term = f"{abs(coeff)}"
        else:
            term = f"{abs(coeff)}x^{i}"
        if coeff < 0:
            term = f"-{term}"
        result.append(term)

    return ' + '.join(result)
