def calculate_score(system: int, points: str) -> list:
    scores = []
    player_score = 0
    opponent_score = 0
    game_over = False

    for point in points:
        if point == 'W':
            player_score += 1
        else:
            opponent_score += 1

        if player_score >= system and player_score - opponent_score >= 2:
            scores.append(f"{player_score}:{opponent_score}")
            game_over = True
        elif opponent_score >= system and opponent_score - player_score >= 2:
            scores.append(f"{player_score}:{opponent_score}")
            game_over = True

        if game_over:
            break

    if not game_over:
        scores.append(f"{player_score}:{opponent_score}")

    return scores
