def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Key and ciphertext must consist only of alphabetic characters.")

    key_length = len(key)
    plaintext = ""

    for i, char in enumerate(ciphertext):
        if char.isalpha():
            shift = ord(key[i % key_length]) - ord('A') if char.isupper() else ord(key[i % key_length]) - ord('a')
            decrypted_char = chr((ord(char) - ord('A') - shift) % 26 + ord('A')) if char.isupper() else chr((ord(char) - ord('a') - shift) % 26 + ord('a'))
            plaintext += decrypted_char
        else:
            plaintext += char

    return plaintext
```

