def minimum_students_to_leave(heights):
    if not heights:
        return 0

    n = len(heights)
    left = 0
    right = n - 1
    count = 0

    while left < right:
        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1
            count += 1

    return count
```

```python
def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("Number of disc pairs must be at least 1")

    # Base cases
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14

    # Recursive relation
    return 2 * hanoi_double_iterative(n - 1) + 2
```
